/bin/bash -lc "curl -fsSL 'https://storage.googleapis.com/encode-pipeline-test-samples/encode-atac-seq-pipeline/ENCSR889WQX/example_output/qc.json' -o example.qc.json
python3 - <<'PY'
import json
x=json.load(open('example.qc.json'))
def walk(v,p=''):
    if isinstance(v,dict):
        for k,z in v.items():
            q=p+'.'+k if p else k
            if 'opt' in k.lower() or 'repro' in k.lower() or 'idr' in k.lower():
                print(q, repr(z)[:500])
            walk(z,q)
    elif isinstance(v,list):
        for i,z in enumerate(v): walk(z,p+'[%d]'%i)
walk(x)
PY"
